(SynthDef(\GendyI, {
  |inbus =0, outbus = 0,
  ampdist = 0, durdist = 1, 
  adparam = 0.5, ddparam = 0.4,
  minfreq = 0.095, maxfreq = 0.98878,
  ampscale=0.5, durscale=0.5,
  numcps=24,
  maxdel = 0.5, del= 0.0, pmul = 1,
  pos = 0, bits =24,
  mix = 0,
  vmix = 0.333, vroom = 0.5, vdamp = 0.5|
  var pan, pitch, input, out, crush;
  input = InFeedback.ar(inbus, 1);
  input = DelayC.ar(input, maxdel, del);
  pitch = Pitch.kr(input)[0] * pmul; //we track the pitch
  pitch.poll;
  pan= Pan2.ar(Gendy1.ar(ampdist, durdist,
    adparam, ddparam,
    minfreq * pitch, pitch * maxfreq,
    ampscale, input.fold(0,1),
    numcps), LinLin.kr(pitch, 0, 44100, -1, 1), 0.3); 
//we feedback the pitch value here
  crush=Decimator.ar(pan, pitch*10, bits);
  crush = XFade2.ar(pan, crush, mix, 1);
  crush=FreeVerb.ar(crush, vmix, vroom, vdamp);
  out = Out.ar(outbus, Limiter.ar(crush, 0.995, 0.1));
// we feedback the pitch value also here
}).add;);

 66339. The Process of Creating a Computational System
mathematics, drawing, and electronics.
The UpicMX project was successful in achieving two different programming 
solutions to convert traces into sound. The first solution was “plastic sonification,” 
which consists of a graphical approximation of the reading of the traces; the function 
obtains, according to a process of conversion, the time and frequency of the pixels 
of the drawing in order to assign each pixel an oscillator in real time. Each of the 
oscillators is superimposed on the next one for a fraction of a second, constantly 
generating an additive synthesis in frequencies so close that beats are produced that 
enrich the resulting timbre (see Code 39.1).
function sonoficarPlastica() {
  loadPixels(); // Loads all pixels in an array. Function of 
p5
  var filasConNegro = []
  var frequencias = []
  //tiempoApixel converts the pixels into a time 
relationship
  var timeActualPix = int(min(tiempoApixel() + 3, width));
  // The following code goes through all pixels column by 
column
  // in each column it scrolls through all the rows and if a 
  // pixel in black adds it to a list where the
  // coordinates with black pixels.
  for (var cont = 0; cont < height; cont++) {
    var pixCanalRojo = pixels[(cont * width + timeActualPix) 
* 4 + 0];
    if (pixCanalRojo == 0) {
      filasConNegro.push(height - cont);
    }
  }
  //The frequency corresponding to each coordinate is 
obtained.
  //that has black in frequency format.
  frequencias = filasConNegro.map(pixNegro => {
    let midi = map(pixNegro, 0, height, notaGrave, 
notaAguda);
    //midi2freq converts the midi note to its corresponding 
frequency

664 Meta-Xenakis
    return midi2freq(midi);
  });
  // For each frequency a 20 millisecond oscillator is 
generated.
  for (var i = 0; i < frequencias.length; i++) {
    var osc = new p5.Oscillator(frequencias[i], ‘sine’);
    // amp, start and stop are functions of the webaudioapi.
    osc.amp(0);
    osc.start();
    osc.amp(0.1, 0.05);
    osc.amp(0, 0.1, 0.05);
    osc.stop(0.2);
  }
}
Code 39.1 
The second type of “sonification,” called ”parametric,” reads and stores the trace 
information in time and frequency parameters, then assigns it to a single oscillator per 
line that modulates its values over time using envelopes in its frequency and amplitude 
parameters. When the “touch” button is pressed, the oscillators are activated and 
change their frequency according to the movement of the base generator trace (see 
Code 39.2).
function sonificarParametrica() {
  destruyeOsc(); // Release all active generators with stop
  //del webaudioapi.
  osciladores = [];
  // compositionTF is an array of arrays in which
  //each internal array contains the stroke points.
  for (var i = 0; i < composicionTF.length; i++) {
    var gestoTMP = composicionTF[i];
    var osc = new p5.Oscillator(composicionTF[i][1][0], 
‘sine’);
    osc.start(composicionTF[i][0][0]);
    // A single oscillator is generated whose frequency 
changes
    // discretely but at a speed that gives us

 66539. The Process of Creating a Computational System
    //a perceptual glissando.
    osc.amp(0.0, 0, composicionTF[i][0][0]);
    osc.amp(0.1, 0.1, composicionTF[i][0][0]);
    // nesting for that goes through each point of each 
stroke and assigns
    //frequency at the corresponding moment (time).
    for (var j = 1; j < gestoTMP[0].length; j++) {
      var tTmp = composicionTF[i][0][j];
      var fTmp = composicionTF[i][1][j];
      var tTmpAnterior = composicionTF[i][0][j - 1];
      osc.freq(fTmp, tTmp - tTmpAnterior, tTmpAnterior);
    }
    // On the last point of each stroke the volume is turned 
down and off.
    var indxtUltimo = gestoTMP[0].length - 1;
    osc.amp(0, 0.1, gestoTMP[0][indxtUltimo] - 0.1);
    osc.stop(gestoTMP[0][indxtUltimo]);
    // All oscillators are added to one array
    //to be able to turn them off in another external 
function.
    osciladores.push(osc);
  }
}
Code 39.2 
Another feature of the project is the incorporation of a grid in both the X and Y axes 
that can be activated or deactivated, depending on the accuracy with which you want 
to manage the times and heights (pitches) in the traces.

